// Verdict tally shared by the Replications page and entry pages.
// Local context: a row with `post_hoc` set (analysis chosen after its results were seen, or no pre-stated criterion;
// list in src/atlas/common/post_hoc.py) keeps its verdict on screen but is excluded from the counts, matching the
// README scoreboard generated by atlas.report.
import type { ReplicationResult } from './types'

export interface Tally {
  pass: number
  partial: number
  fail: number
  na: number
  preStated: number
  postHoc: number
}

export function tally(rows: ReplicationResult[]): Tally {
  const pre = rows.filter((r) => !r.post_hoc)
  const n = (v: ReplicationResult['verdict']) => pre.filter((r) => r.verdict === v).length
  return { pass: n('pass'), partial: n('partial'), fail: n('fail'), na: n('n/a'), preStated: pre.length, postHoc: rows.length - pre.length }
}
